<?php
namespace qqworld_collector\module\pseudo_original; use qqworld_collector\lib; class simulate_manual_publish extends lib { var $log_id = 'pseudo-original'; public function init() { add_action( 'rest_api_init', array($this, 'rest_api_init') ); add_action( 'qqworld-collector-pseudo-original-simulate-manual-publish', array($this, 'do_simulate_manual_publish') ); add_action( 'wp_ajax_qqworld-collector-pseudo-original-simulate-manual-publish-add-cron-task', array($this, 'add_cron_task') ); add_action( 'wp_ajax_nopriv_qqworld-collector-pseudo-original-simulate-manual-publish-add-cron-task', array($this, 'add_cron_task') ); add_action( 'wp_ajax_qqworld-collector-pseudo-original-simulate-manual-publish-clear-a-cron', array($this, 'clear_a_cron') ); add_action( 'wp_ajax_nopriv_qqworld-collector-pseudo-original-simulate-manual-publish-clear-a-cron', array($this, 'clear_a_cron') ); add_action( 'wp_ajax_qqworld-collector-pseudo-original-simulate-manual-publish-clear-all-crons', array($this, 'clear_all_the_crons') ); add_action( 'wp_ajax_nopriv_qqworld-collector-pseudo-original-simulate-manual-publish-clear-all-crons', array($this, 'clear_all_the_crons') ); } public function rest_api_init() { $namespace = 'pseudo_original/v1'; register_rest_route( $namespace, 'simulate_manual_publish', array( 'methods' => 'GET', 'callback' => array($this, 'debug_simulate_manual_publish'), 'update_callback' => null, 'permission_callback' => '__return_true', 'schema' => null ) ); } public function debug_simulate_manual_publish() { $args = array( 'post_type' => 'post', 'post_status' => 'pending', 'number' => '1', 'schedule' => 'monthly', 'exclude_time' => '23:00-08:00' ); $this->do_simulate_manual_publish($args); } public function isInExcludeTime($exclude_time) { list($start_time_str, $end_time_str) = explode('-', $exclude_time); $current_timestamp = current_time('timestamp'); $start_timestamp = strtotime(trim($start_time_str)); $end_timestamp = strtotime(trim($end_time_str)); if ($start_timestamp < $end_timestamp) { return ($current_timestamp >= $start_timestamp && $current_timestamp <= $end_timestamp); } else { return ($current_timestamp >= $start_timestamp || $current_timestamp <= $end_timestamp); } } public function do_simulate_manual_publish($args) { do_action( 'qqworld-collector-log', $this->log_id, 'Simulate manual publish ($args):', print_r($args, true) ); if (isset($args['exclude_time']) && $args['exclude_time']) { if ($this->isInExcludeTime($args['exclude_time'])) { do_action( 'qqworld-collector-log', $this->log_id, 'Simulate manual publish no publish by exclude time:', date('Y-m-d H:i:s', current_time('timestamp')) ); return; } } $post_args = array( 'post_type' => $args['post_type'], 'post_status' => $args['post_status'], 'posts_per_page' => $args['number'], 'order_by' => 'ID', 'order' => 'ASC' ); if ($this->options->qc_detectd_duplicate_titles) { $duplicated_post_ids = get_transient( 'qqworld-collector-duplicated-post-ids' ); if ($duplicated_post_ids) $post_args['post__not_in'] = $duplicated_post_ids; } $failed_post_ids = get_transient( 'qqworld-collector-failed-post-ids' ); if ($failed_post_ids) { if (isset($post_args['post__not_in']) && $post_args['post__not_in']) $post_args['post__not_in'] = array_merge($post_args['post__not_in'], $failed_post_ids); else $post_args['post__not_in'] = $failed_post_ids; } if (isset($args['terms']) && !empty($args['terms'])) { $terms = $args['terms']; $post_args['tax_query'] = array( 'relation' => 'AND' ); foreach ($terms as $taxonomy => $term_ids) { if ($args['each'] == 1 && $taxonomy == 'category') continue; $post_args['tax_query'][] = array( 'taxonomy' => $taxonomy, 'terms' => $term_ids, 'field' => 'id' ); } } if (!isset($terms['category']) || $args['each'] == 0) { $number = explode('-', $args['number']); $post_args['posts_per_page'] = count($number) > 1 ? rand($number[0], $number[1]) : $number[0]; if ($new_post_args['order'] == 'rand') { $new_post_args['orderby'] = 'rand'; unset($new_post_args['order']); } $new_post_args = apply_filters( 'qqworld-collector-pseudo-original-simulate-manual-publish-new-post-args', $new_post_args ); $posts = get_posts($post_args); do_action( 'qqworld-collector-log', $this->log_id, 'Start to simulate manual publish: ($post_args)', print_r($post_args, true) ); do_action( 'qqworld-collector-log', $this->log_id, 'Simulate manual publish to getting posts:', count($posts) ); if (!empty($posts)) { if (!empty($posts)) foreach ($posts as $post) { if ($this->options->qc_detectd_duplicate_titles) { $post_metas = array(); if ($this->options->qc_detectd_duplicate_post_meta) { $post_metas[$this->options->qc_detectd_duplicate_post_meta] = get_post_meta($post->ID, $this->options->qc_detectd_duplicate_post_meta, true); } $posts = $GLOBALS['QC']->check_duplicated_title->check_duplicated_title($post->ID, $post->post_title, $post_metas, array('publish', 'private')); if (count($posts)) { $duplicated_post_ids = get_transient( 'qqworld-collector-duplicated-post-ids' ); if ($duplicated_post_ids) $duplicated_post_ids[] = $post->ID; else $duplicated_post_ids = array($post->ID); set_transient( 'qqworld-collector-duplicated-post-ids', $duplicated_post_ids ); continue; } } $failed_post_ids = get_transient( 'qqworld-collector-failed-post-ids' ); if ($failed_post_ids) $failed_post_ids[] = $post->ID; else $failed_post_ids = array($post->ID); set_transient( 'qqworld-collector-failed-post-ids', $failed_post_ids ); do_action( 'qqworld-collector-log', $this->log_id, 'simulate manual publishing: ', $post->post_title . ' ('.$post->ID.')' ); $postdata = array( 'ID' => $post->ID, 'post_status' => 'publish' ); if ( apply_filters( 'qqworld-collector-auxiliary-use-current-date-default-value', 1) ) { $postdata['post_date'] = get_date_from_gmt(date('Y-m-d H:i:s')); $postdata['post_date_gmt'] = date('Y-m-d H:i:s'); } if ($this->options->qc_asa_general_mode == 'auto') { do_action( 'qqworld-collector-log', $this->log_id, 'simulate manual publishing: ', $post->post_title . ' (Auto save attachments first)' ); $post->post_content = $GLOBALS['QC']->auto_save_attachment->save_attachment->save_remote_attachment($post->post_content, array('post_id' => $post->ID)); $GLOBALS['QC']->auto_save_attachment->save_attachment->fetch_images_from_post_meta($post->ID, $post); if (!empty($post->post_content)) $postdata['post_content'] = $post->post_content; } $post_id = wp_update_post($postdata); if ($post_id && !is_wp_error($post_id)) { } else { $message = is_wp_error($post_id) ? ': ' . $post_id->get_error_message() : ', no error message.'; do_action( 'qqworld-collector-log', $this->log_id, 'simulate manual publishing failed $post_id ('.$post->ID.'): ', $message ); } } } } else { do_action( 'qqworld-collector-log', $this->log_id, 'Simulate manual publish to publish each categories:', print_r($terms['category'], true) ); foreach ($terms['category'] as $category_id) { $new_post_args = $post_args; $new_post_args['tax_query'][] = array( 'taxonomy' => 'category', 'terms' => array($category_id), 'field' => 'id' ); $number = explode('-', $args['number']); if (count($number) > 1) { $new_post_args['posts_per_page'] = rand($number[0], $number[1]); } else { $new_post_args['posts_per_page'] = $number[0]; } if ($new_post_args['order'] == 'rand') { $new_post_args['orderby'] = 'rand'; unset($new_post_args['order']); } $new_post_args = apply_filters( 'qqworld-collector-pseudo-original-simulate-manual-publish-new-post-args', $new_post_args ); $posts = get_posts($new_post_args); do_action( 'qqworld-collector-log', $this->log_id, 'Start to simulate manual publish: ($new_post_args)', print_r($new_post_args, true) ); do_action( 'qqworld-collector-log', $this->log_id, 'Simulate manual publish to getting posts:', count($posts) ); if (!empty($posts)) { foreach ($posts as $post) { if ($this->options->qc_detectd_duplicate_titles) { $post_metas = array(); if ($this->options->qc_detectd_duplicate_post_meta) { $post_metas[$this->options->qc_detectd_duplicate_post_meta] = get_post_meta($post->ID, $this->options->qc_detectd_duplicate_post_meta, true); } $_posts = $GLOBALS['QC']->check_duplicated_title($post->ID, $post->post_title, $post_metas, array('publish', 'private')); if (count($_posts)) { $duplicated_post_ids = get_transient( 'qqworld-collector-duplicated-post-ids' ); if ($duplicated_post_ids) $duplicated_post_ids[] = $post->ID; else $duplicated_post_ids = array($post->ID); set_transient( 'qqworld-collector-duplicated-post-ids', $duplicated_post_ids ); continue; } } $failed_post_ids = get_transient( 'qqworld-collector-failed-post-ids' ); if ($failed_post_ids) $failed_post_ids[] = $post->ID; else $failed_post_ids = array($post->ID); set_transient( 'qqworld-collector-failed-post-ids', $failed_post_ids ); do_action( 'qqworld-collector-log', $this->log_id, 'simulate manual publishing: ', $post->post_title . ' ('.$post->ID.')' ); $postdata = array( 'ID' => $post->ID, 'post_status' => 'publish' ); if ( apply_filters( 'qqworld-collector-auxiliary-use-current-date-default-value', 1) ) { $postdata['post_date'] = get_date_from_gmt(date('Y-m-d H:i:s')); $postdata['post_date_gmt'] = date('Y-m-d H:i:s'); } if ($this->options->qc_asa_general_mode == 'auto') { do_action( 'qqworld-collector-log', $this->log_id, 'simulate manual publishing: ', $post->post_title . ' (Auto save attachments first)' ); $post->post_content = $GLOBALS['QC']->auto_save_attachment->save_attachment->save_remote_attachment($post->post_content, array('post_id' => $post->ID)); $GLOBALS['QC']->auto_save_attachment->save_attachment->fetch_images_from_post_meta($post->ID, $post); if (!empty($post->post_content)) $postdata['post_content'] = $post->post_content; } $post_id = wp_update_post($postdata); if ($post_id && !is_wp_error($post_id)) { } else { $message = is_wp_error($post_id) ? ': ' . $post_id->get_error_message() : ', no error message.'; do_action( 'qqworld-collector-log', $this->log_id, 'simulate manual publishing failed $post_id ('.$post->ID.'): ', $message ); } } } } } } public function get_cron_table_row($options) { if (!isset($options['post_type']) || empty($options['post_type'])) $options['post_type'] = 'post'; if (!isset($options['post_status']) || empty($options['post_status'])) $options['post_status'] = 'pending'; $post_type = get_post_type_object($options['post_type']); if (isset($options['terms'])) { $taxonomies = array(); foreach ($options['terms'] as $taxonomy => $terms) { $tax = get_taxonomy($taxonomy); $line = '<strong>'.$tax->label.'</strong>' . __(': ', $this->text_domain); $terms_list = array(); foreach ($terms as $term_id) { $term = get_term($term_id, $taxonomy); $terms_list[] = $term->name; } $line .= implode(', ', $terms_list); $taxonomies[] = $line; } $taxonomies = implode('<br />', $taxonomies); if ($options['each'] == 1) $taxonomies .= '<p>' . __('Each selected term publishes a specified number of posts.', $this->text_domain) . '</p>'; } else { $taxonomies = __('Unspecified taxonomies', $this->text_domain); } $post_status = get_post_status_object($options['post_status']); $schedules = wp_get_schedules(); $exclude_time = isset($options['exclude_time']) ? '<br />'.sprintf(sprintf(__('%s: ', $this->text_domain), __('Exclude Time', $this->text_domain)).'<strong>%s</strong>', $options['exclude_time']) : ''; $args = $options; unset($args['timestamp']); return '<tr>
	<th scope="row" class="check-column"></th>
	<td>'.$post_type->label.'</td>
	<td>'.$taxonomies.'</td>
	<td>'.$post_status->label.'</td>
	<td>'.$options['number'].'</td>
	<td>'.$schedules[$options['schedule']]['display'].$exclude_time.'</td>
	<td>'.date('Y-m-d H:i:s', $options['timestamp'] + ( get_option( 'gmt_offset' ) * HOUR_IN_SECONDS )).'</td>
	<td><button type="button" class="clear-a-cron button qc-icon delete" data-args="'.base64_encode(json_encode($args)).'">'.__('Delete').'</button></td>
</tr>'; } public function add_cron_task() { if (!current_user_can($this->options->qc_authorization_who_can_use)) return; $schedule = $_POST['schedule']; $args = array( 'post_type' => $_POST['post_type'], 'post_status' => $_POST['post_status'], 'number' => $_POST['number'], 'schedule' => $schedule, 'exclude_time' => $_POST['exclude_time'] ); if (isset($_POST['terms'])) { $args['terms'] = $_POST['terms']; $args['each'] = $_POST['each']; } $timestamp = strtotime($_POST['from']) > current_time('timestamp') ? time() + (strtotime($_POST['from']) - current_time('timestamp')) : time(); wp_schedule_event( $timestamp, $schedule, 'qqworld-collector-pseudo-original-simulate-manual-publish', array($args)); $schedules = wp_get_schedules(); $options = $args; $options['timestamp'] = $timestamp; $results = array( 'success' => 1, 'html' => $this->get_cron_table_row($options), 'msg' => __('The scheduled task was successfully created.', $this->text_domain), 'args' => $args ); print json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function clear_a_cron() { if ( !current_user_can( $this->options->qc_authorization_who_can_use ) ) return; $args = json_decode(base64_decode($_POST['args']), true); $timestamp = wp_next_scheduled( 'qqworld-collector-pseudo-original-simulate-manual-publish', array($args) ); if ($timestamp) { wp_unschedule_event( $timestamp, 'qqworld-collector-pseudo-original-simulate-manual-publish', array($args) ); $results = array('success' => 1, 'timestamp' => $timestamp, 'msg' => __('Successfully deleted schedule.', $this->text_domain), 'args' => $args); } else { $results = array('success' => 0,'timestamp' => $timestamp, 'msg' => __('Deleted schedule faied.', $this->text_domain), 'args' => $args); } echo json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function clear_all_the_crons() { if (!current_user_can($this->options->qc_authorization_who_can_use)) return; $cleaned = $this->clear_all_crons( 'qqworld-collector-pseudo-original-simulate-manual-publish' ); if ($cleaned) { $results = array('success' => 1, 'msg' => __('Successfully cleared all Crons.', $this->text_domain)); } else { $results = array('success' => 0, 'msg' => __('No Crons found.', $this->text_domain)); } echo json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } } ?>